  private async request<T>(
    path: string,
    method: string,
    expectedStatus: number,
    responseSchemaName: string,
    errorSchemaNames: Readonly<Record<number, string>>,
    body?: unknown,
    requestSchemaName: string | null = null,
  ): Promise<T> {
    if (requestSchemaName) {
      const requestError = validateControlApiValue(requestSchemaName, body);
      if (requestError) throw new ControlApiContractViolationError("request", requestSchemaName, requestError);
    }
    const headers = new Headers();
    if (this.auth.mode !== "cookie") headers.set("authorization", `Bearer ${this.auth.token}`);
    if (this.teamId) headers.set("x-team-id", this.teamId);
    if (body !== undefined) headers.set("content-type", "application/json");
    const requestPath = this.auth.mode === "cookie" ? path.replace(/^\/v1(?=\/|$)/, "") : path;
    const response = await this.fetchImpl(`${this.baseUrl}${requestPath}`, {
      method,
      headers,
      credentials: this.auth.mode === "cookie" ? "include" : "omit",
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    const text = await response.text();
    let payload: unknown = null;
    if (text) {
      try { payload = JSON.parse(text) as unknown; }
      catch { payload = text; }
    }
    if (!response.ok) {
      const errorSchemaName = errorSchemaNames[response.status];
      if (errorSchemaName) {
        const errorResponseError = validateControlApiValue(errorSchemaName, payload);
        if (errorResponseError) {
          throw new ControlApiContractViolationError("response", errorSchemaName, errorResponseError, response.status);
        }
      }
      throw new ControlApiError(response.status, payload);
    }
    if (response.status !== expectedStatus) {
      throw new ControlApiContractViolationError(
        "response", responseSchemaName, `expected HTTP ${expectedStatus}, received ${response.status}`, response.status,
      );
    }
    const responseError = validateControlApiValue(responseSchemaName, payload);
    if (responseError) {
      throw new ControlApiContractViolationError("response", responseSchemaName, responseError, response.status);
    }
    return payload as T;
  }
